import type { Assessment } from './assessment-model';

export const AssessmentInputInputTypeKeyToLabel = {
  'Strength': 'Strength',
  'DevelopmentArea': 'Development Area',
  'ObjectiveKPI': 'Objective KPI'
} as const;
export type AssessmentInputInputTypeKey = keyof typeof AssessmentInputInputTypeKeyToLabel;

export interface AssessmentInput {
  /**
   * @displayName Assessment Input ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Assessment Input Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  assessmentInputName: string;
  /**
   * @displayName Assessment
   * @validationRule Required for create/update operations
   */
  assessment: Pick<Assessment, 'id' | 'assessmentName'>;
  /**
   * @displayName Input Text
   * @validationRule Required for create/update operations
   */
  inputText: string;
  /**
   * @displayName Input Type
   * @validationRule Required for create/update operations
   */
  inputTypeKey: AssessmentInputInputTypeKey;
  /**
   * @displayName Sequence
   * @validationRule Required for create/update operations
   */
  sequence: number;
}

export const _AssessmentInput = 'AssessmentInput' as const;